        public Result { rows=List.copyOf(rows);reconciliations=Collections.unmodifiableMap(new LinkedHashMap<>(reconciliations));disclosures=List.copyOf(disclosures);dimension=dimension==null?RegulatoryFormatCatalog.Scope.BRANCH:dimension;currentBranchSources=currentBranchSources==null?List.of():List.copyOf(currentBranchSources);comparisonBranchSources=comparisonBranchSources==null?List.of():List.copyOf(comparisonBranchSources); }
        public Result(UUID id,UUID versionId,UUID templateId,int mappingVersion,int calculationVersion,StatementDefinition definition,String institution,String branch,LocalDate from,LocalDate through,LocalDate comparisonFrom,LocalDate comparisonThrough,OffsetDateTime recordedCutoff,OffsetDateTime comparisonCutoff,UUID policyId,int policyVersion,UUID closeReviewId,String closeChecksum,UUID comparisonCloseId,String comparisonCloseChecksum,String coverage,String status,List<RowValue> rows,Map<String,BigDecimal> reconciliations,List<String> disclosures,UUID mappingReviewer,String mappingApprovalEvidence,OffsetDateTime generatedAt,UUID priorResultId){this(id,versionId,templateId,mappingVersion,calculationVersion,definition,institution,branch,from,through,comparisonFrom,comparisonThrough,recordedCutoff,comparisonCutoff,policyId,policyVersion,closeReviewId,closeChecksum,comparisonCloseId,comparisonCloseChecksum,coverage,status,rows,reconciliations,disclosures,mappingReviewer,mappingApprovalEvidence,generatedAt,priorResultId,RegulatoryFormatCatalog.Scope.BRANCH,List.of(),List.of(),null,null,null,null);}
        @com.fasterxml.jackson.annotation.JsonIgnore public List<RowValue> getVisibleRows(){return rows.stream().filter(r->r.visible() || r.mandatory()).toList();}
        Result withId(UUID id){return copy(id,priorResultId);}
