        private Result copy(UUID id,UUID prior){return new Result(id,versionId,templateId,mappingVersion,calculationVersion,definition,institution,branch,from,through,comparisonFrom,comparisonThrough,recordedCutoff,comparisonCutoff,policyId,policyVersion,closeReviewId,closeChecksum,comparisonCloseId,comparisonCloseChecksum,coverage,status,rows,reconciliations,disclosures,mappingReviewer,mappingApprovalEvidence,generatedAt,prior,dimension,currentBranchSources,comparisonBranchSources,institutionPeriodId,comparisonInstitutionPeriodId,institutionSourceChecksum,comparisonInstitutionSourceChecksum);}
        Result institutionSource(UUID period,String checksum,List<BranchSource> current,UUID comparePeriod,String compareChecksum,List<BranchSource> compare){var requiredRows=new ArrayList<RowValue>(rows);requiredRows.add(new RowValue("INSTITUTION_SOURCE","Institution source","Chanzo cha taasisi",RowKind.NOTE,Unit.NONE,null,null,"TEXT","TEXT",true,false,true,period+"; SHA256="+checksum,period+"; SHA256="+checksum));sourceRows(requiredRows,current,"CURRENT");sourceRows(requiredRows,compare,"COMPARISON");return new Result(id,versionId,templateId,mappingVersion,calculationVersion,definition,institution,branch,from,through,comparisonFrom,comparisonThrough,recordedCutoff,comparisonCutoff,policyId,policyVersion,null,null,null,null,coverage,status,requiredRows,reconciliations,disclosures,mappingReviewer,mappingApprovalEvidence,generatedAt,priorResultId,RegulatoryFormatCatalog.Scope.INSTITUTION,current,compare,period,comparePeriod,checksum,compareChecksum);}
